\begin{tikzpicture}[font=\sffamily, scale=1.2]
  % Define coordinates
  % A at origin (0,0)
  \coordinate (A) at (0,0);
  % B along x-axis, say (4,0)
  \coordinate (B) at (4,0);
  % D at some angle, say 60 degrees, length 3 -> (1.5, 2.598)
  \coordinate (D) at (1.5, 2.598);
  % C = B + D - A = (4,0) + (1.5, 2.598) - (0,0) = (5.5, 2.598)
  \coordinate (C) at (5.5, 2.598);

  % E lies on CD produced such that CD : CE = 1 : 2
  % Since CD = b, CE = 2b (total length from C is twice CD in direction CD)
  % Vector D - C = vector -b. Vector C - D = vector b.
  % E is such that C is between D and E, and CE = 2 CD.
  % Let's compute E: E = C + 2(C - D) = 3C - 2D = 3(5.5, 2.598) - 2(1.5, 2.598) = (16.5 - 3, 7.794 - 5.196) = (13.5, 2.598) - wait.
  % Let's use simple vector geometry: C = D + b, E = C + 2b = D + 3b.
  % b = vector CD = C - D = (4, 0).
  % D = (1.5, 2.598).
  % E = (1.5, 2.598) + 3(4, 0) = (13.5, 2.598). That's too far right, my b is horizontal?
  % Wait! ABCD is a parallelogram, AB = DC.
  % A=(0,0), B=(4,0). So AB = (4,0).
  % Since ABCD is a parallelogram, DC = AB = (4,0).
  % So C - D = (4,0) => C = D + (4,0).
  % If D = (1.5, 2.598), then C = (5.5, 2.598).
  % Vector CD = b = (4,0).
  % E lies on CD produced such that CD : CE = 1 : 2.
  % CD = b, so CE = 2b? Wait, "CD : CE = 1 : 2" means length of CD : length of CE = 1 : 2.
  % So CE = 2CD = 2b. Since E is on CD produced, E = C + 2b = (5.5, 2.598) + 2(4,0) = (13.5, 2.598).
  % That makes E very far to the right. Let's adjust D to have a more general position or scale down.
  % Let's redefine:
  % Let A = (0,0), D = (2, 3), so AD vector is (2,3). M is midpoint of AD -> (1, 1.5).
  % CD = AB. Let AB = b.
  % Let's set B = (5, 0), so b = (5, 0) is horizontal? No, standard parallelogram:
  % Let A=(0,0), B=(5,0), D=(2,3), C=(7,3).
  % Then CD = C - D = (5,0) = b.
  % E lies on CD produced, CD : CE = 1 : 2.
  % Since CD = b, CE = 2b. E = C + 2(CD) = C + 2b = (7,3) + 2(5,0) = (17, 3). Still wide.
  % Let's make b shorter: AB = 3, so B=(3,0), b = (3,0).
  % D = (1.5, 2.5), C = (4.5, 2.5).
  % E = C + 2b = (4.5, 2.5) + 2(3,0) = (10.5, 2.5).
  % Let's use coordinates:
  \coordinate (A) at (0,0);
  \coordinate (B) at (4,0);
  \coordinate (D) at (1,2.5);
  \coordinate (C) at ($(B)+(D)-(A)$); % (5,2.5)

  % CD = b = C - D = (4, 0).
  % Wait, if B=(4,0) and A=(0,0), then AB = (4,0).
  % ABCD is a parallelogram, so DC = AB = (4,0) => C - D = (4,0) => C = D + (4,0).
  % D = (1, 2.5) => C = (5, 2.5).
  % Then CD = C - D = (4, 2.5) - (1, 2.5) = (4,0) = b.
  % E lies on CD produced such that CD : CE = 1 : 2.
  % Since CD has length b (vector b = (4,0)), CE = 2b = (8,0).
  % E = C + 2(CD) = (5, 2.5) + (8, 0) = (13, 2.5).
  % Let's plot E at (9, 2.5) to keep it compact, meaning we change coordinates:
  % Let b be vector with length. Let's just place points visually and use calculated coordinates.

  \coordinate (A) at (0,0);
  \coordinate (B) at (4,0);
  \coordinate (D) at (1.5, 2.5);
  \coordinate (C) at (5.5, 2.5);
  % E is on CD produced, CE = 2 * CD.
  % Vector CD = (4, 0). Vector CE = 2 * (4, 0) = (8, 0).
  % E = C + (8, 0) = (13.5, 2.5). To make drawing neat, let's place E at (9.5, 2.5) and let CD:CE be something else? No, must obey question.
  % We can just draw E further out.
  \coordinate (E) at (9.5, 2.5); % wait, if C=(5.5,2.5) and D=(1.5,2.5), CD = 4. CE = 4 + something?
  % If CD : CE = 1 : 2, then CE = 2 * CD = 2 * 4 = 8.
  % So distance from C to E is 8. C is at 5.5, so E is at 5.5 + 8 = 13.5.
  % Let's scale down everything horizontally so it fits nicely.

  % Let's redefine using polar/relative for clarity:
  \coordinate (A) at (0,0);
  \coordinate (B) at (3,0);
  \coordinate (D) at (1,2);
  \coordinate (C) at (4,2);
  % CD = (3,0) = b.
  % CE = 2b = (6,0) => E = (4+6, 2) = (10,2).
  \coordinate (E) at (10,2);

  % M is midpoint of AD
  \coordinate (M) at ($(A)!.5!(D)$);

  % N is a point on BC such that BN : BC = 1 : 4.
  % BN = a. Since BN : BC = 1 : 4, BC = 4a.
  % Also ABCD is a parallelogram, so BC = AD = b? Wait!
  % Read carefully: "BN = a and CD = b. Express ... in terms of a and/or b"
  % Note: CD = b, and since ABCD is a parallelogram, AB = CD = b, and BC = AD.
  % BN : BC = 1 : 4 means N is on BC, 1/4 of the way from B to C.
  \coordinate (N) at ($(B)!0.25!(C)$);

  % Draw parallelogram ABCD
  \draw (A) -- (B) -- (C) -- (D) -- cycle;

  % Draw line from C through E (CD produced)
  \draw (D) -- (E);

  % Draw lines for vectors/segments mentioned: AM, BM, BE
  \draw (A) -- (M);
  \draw (B) -- (M);
  \draw (B) -- (E);

  % Labels for points
  \node[left] at (A) {A};
  \node[right] at (B) {B};
  \node[above right] at (C) {C};
  \node[left] at (D) {D};
  \node[above] at (M) {M};
  \node[above] at (N) {N};
  \node[above right] at (E) {E};

  % Optional: draw small ticks or markers if helpful, but keep it clean O-Level style
  \fill (A) circle (1.5pt);
  \fill (B) circle (1.5pt);
  \fill (C) circle (1.5pt);
  \fill (D) circle (1.5pt);
  \fill (M) circle (1.5pt);
  \fill (N) circle (1.5pt);
  \fill (E) circle (1.5pt);

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=1.2]
  % Define coordinates
  \coordinate (A) at (0,0);
  \coordinate (B) at (4,0);
  \coordinate (D) at (1.5, 2.5);
  \coordinate (C) at (5.5, 2.5);

  % E lies on CD produced such that CD : CE = 1 : 2
  % Vector CD = (4, 0). CE = 2 * CD = (8, 0). E = C + (8, 0) = (13.5, 2.5)
  \coordinate (E) at (13.5, 2.5);

  % M is midpoint of AD
  \coordinate (M) at ($(A)!.5!(D)$);

  % N is a point on BC such that BN : BC = 1 : 4
  \coordinate (N) at ($(B)!0.25!(C)$);

