  % Draw line from C through E (CD produced)
  \draw (D) -- (E);

  % Draw lines for vectors/segments mentioned: AM, BM, BE
  \draw (A) -- (M);
  \draw (B) -- (M);
  \draw (B) -- (E);

  % Labels for points
  \node[left] at (A) {A};
  \node[below left] at (B) {B};
  \node[above right] at (C) {C};
  \node[left] at (D) {D};
  \node[above left] at (M) {M};
  \node[above left] at (N) {N};
  \node[above] at (E) {E};

  % Point dots
  \fill (A) circle (1.5pt);
  \fill (B) circle (1.5pt);
  \fill (C) circle (1.5pt);
  \fill (D) circle (1.5pt);
