\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=1.2]
  % Define coordinates
  \coordinate (A) at (0,0);
  \coordinate (B) at (6,0);
  \coordinate (D) at (1.5, 2.5);
  \coordinate (C) at (7.5, 2.5);

  % E lies on CD produced such that CD : CE = 1 : 2
  % Vector CD = (6, 0). CE = 2 * CD = (12, 0). E = C + (12, 0) = (19.5, 2.5)
  % Let's scale down horizontally to make it fit nicely
  \coordinate (A) at (0,0);
  \coordinate (B) at (4,0);
  \coordinate (D) at (1.5, 2.5);
  \coordinate (C) at (5.5, 2.5);
  \coordinate (E) at (11.5, 2.5); % CE = 2 * CD = 2 * 4 = 8 -> 5.5 + 6 = 11.5? Wait, C=(5.5), CD length is 4. CE = 8. So E = 5.5 + 8 = 13.5.

  \coordinate (E) at (13.5, 2.5);

  % M is midpoint of AD
  \coordinate (M) at ($(A)!.5!(D)$);

  % N is a point on BC such that BN : BC = 1 : 4
  \coordinate (N) at ($(B)!0.25!(C)$);

  % Draw parallelogram ABCD
  \draw (A) -- (B) -- (C) -- (D) -- cycle;

  % Draw line from C through E (CD produced)
  \draw (D) -- (E);

  % Draw lines for vectors/segments mentioned: AM, BM, BE
  \draw (A) -- (M);
  \draw (B) -- (M);
  \draw (B) -- (E);

  % Labels for points
  \node[left] at (A) {A};
  \node[below left] at (B) {B};
  \node[above right] at (C) {C};
  \node[left] at (D) {D};
  \node[above left] at (M) {M};
